/* ============================================================
   MENU V2 — BTD6-inspired Rebel command interface
   ============================================================ */
:root {
  --m-panel: rgba(12, 20, 32, 0.9);
  --m-panel-2: rgba(25, 39, 56, 0.9);
  --m-line: rgba(129, 191, 222, 0.2);
  --m-line-strong: rgba(157, 224, 255, 0.55);
  --m-cyan: #7fe2ff;
  --m-cyan-deep: #2b8fd0;
  --m-gold: #f7cf76;
  --m-gold-2: #e0a13c;
  --m-shadow: 0 22px 54px rgba(0, 0, 0, 0.44);
}

.icon-defs { position: absolute; width: 0; height: 0; overflow: hidden; }

/* ---------- deep-space backdrop ---------- */
.space-bg {
  background:
    radial-gradient(ellipse 56% 44% at 80% 30%, rgba(38, 129, 179, 0.34), transparent 66%),
    radial-gradient(ellipse 48% 48% at 12% 78%, rgba(112, 62, 160, 0.24), transparent 70%),
    radial-gradient(ellipse 32% 22% at 52% 12%, rgba(233, 163, 74, 0.1), transparent 70%),
    radial-gradient(ellipse 120% 110% at 50% 45%, transparent 34%, rgba(0, 0, 0, 0.66) 100%),
    linear-gradient(155deg, #04070d 0%, #07101d 46%, #0a1726 100%);
}
.space-bg::before {
  content: "";
  position: absolute;
  inset: -10%;
  background:
    radial-gradient(ellipse 42% 24% at 74% 36%, rgba(67, 178, 219, 0.13), transparent 70%),
    radial-gradient(ellipse 30% 19% at 20% 68%, rgba(168, 96, 206, 0.1), transparent 72%),
    repeating-linear-gradient(104deg, transparent 0 120px, rgba(113, 187, 218, 0.022) 122px 124px, transparent 126px 250px);
  pointer-events: none;
}
.space-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(1.5px 1.5px at 8% 22%, rgba(255, 244, 216, 0.9), transparent 100%),
    radial-gradient(1px 1px at 19% 66%, rgba(255, 244, 216, 0.62), transparent 100%),
    radial-gradient(2px 2px at 43% 17%, rgba(213, 241, 255, 0.8), transparent 100%),
    radial-gradient(1px 1px at 67% 72%, rgba(255, 244, 216, 0.55), transparent 100%),
    radial-gradient(1.6px 1.6px at 88% 37%, rgba(255, 244, 216, 0.8), transparent 100%);
  background-size: 460px 390px;
  opacity: 0.5;
  pointer-events: none;
}
.space-bg-dim { filter: saturate(0.92) brightness(0.86); }
.nebula {
  position: absolute;
  border-radius: 50%;
  filter: blur(42px);
  mix-blend-mode: screen;
  pointer-events: none;
}
.nebula-a {
  width: 64vw; height: 42vh;
  right: -10vw; top: 1vh;
  background: radial-gradient(ellipse, rgba(49, 170, 218, 0.34), rgba(41, 72, 160, 0.12) 55%, transparent 72%);
  animation: nebula-pulse 18s ease-in-out infinite;
}
.nebula-b {
  width: 46vw; height: 38vh;
  left: -8vw; bottom: -8vh;
  background: radial-gradient(ellipse, rgba(145, 76, 188, 0.24), rgba(45, 40, 112, 0.08) 56%, transparent 74%);
  animation: nebula-pulse 23s ease-in-out infinite reverse;
}
@keyframes nebula-pulse {
  0%, 100% { opacity: 0.55; transform: scale(1); }
  50% { opacity: 0.82; transform: scale(1.05); }
}

.stars { opacity: 0.62; }
.stars-b { opacity: 0.28; }
.planet-main {
  width: min(52vw, 660px);
  right: max(-17vw, -170px);
  top: 7vh;
  background:
    radial-gradient(circle at 30% 26%, #d5edf4 0%, #8fc2d1 6%, #51869d 18%, #2b5872 38%, #17314a 59%, #0a1727 79%, #040911 100%);
  box-shadow:
    inset -72px -52px 126px rgba(0, 0, 0, 0.86),
    inset 24px 18px 74px rgba(255, 255, 255, 0.13),
    0 0 120px rgba(88, 172, 206, 0.18);
}
.planet-main::before {
  background:
    repeating-linear-gradient(171deg, transparent 0 24px, rgba(205, 238, 244, 0.06) 25px 30px, transparent 31px 50px),
    radial-gradient(26% 13% at 31% 39%, rgba(238, 251, 253, 0.16), transparent 70%),
    radial-gradient(34% 10% at 55% 62%, rgba(231, 248, 252, 0.1), transparent 70%),
    radial-gradient(60% 35% at 38% 28%, rgba(235, 250, 252, 0.14), transparent 70%);
}
.planet-main::after {
  box-shadow:
    inset -14px 0 42px rgba(159, 220, 240, 0.2),
    inset 0 0 3px rgba(213, 244, 252, 0.48),
    0 0 34px rgba(122, 204, 234, 0.08);
}
.moon-mini {
  right: 41%;
  top: 14%;
  opacity: 0.58;
}
.screen-vignette {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 34%, rgba(0, 0, 0, 0.48) 100%),
    linear-gradient(90deg, rgba(2, 5, 10, 0.64) 0%, transparent 34%, transparent 68%, rgba(2, 5, 10, 0.18) 100%);
}
.start-screen .screen-vignette {
  background:
    linear-gradient(90deg, rgba(2, 5, 11, 0.9) 0%, rgba(2, 5, 11, 0.62) 35%, rgba(2, 5, 11, 0.12) 72%, transparent 100%),
    radial-gradient(ellipse at 46% 48%, transparent 30%, rgba(0, 0, 0, 0.36) 100%);
}
.start-screen::before, .start-screen::after { content: none; }

/* ---------- proper spacecraft ---------- */
.ship-layer { position: absolute; inset: 0; pointer-events: none; }
.ship { position: absolute; display: block; overflow: visible; }
.ship.destroyer {
  width: min(37vw, 480px);
  right: -2vw;
  top: 12%;
  opacity: 0.76;
  filter: drop-shadow(0 18px 26px rgba(0, 0, 0, 0.64)) drop-shadow(0 0 18px rgba(91, 201, 255, 0.18));
  animation: sd-drift 26s ease-in-out infinite;
}
.ship.cruiser {
  width: min(21vw, 270px);
  left: -4vw;
  top: 13%;
  opacity: 0.34;
  filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.6));
  animation: cruiser-drift 34s ease-in-out infinite;
}
.ship.fighter { width: min(12vw, 158px); filter: drop-shadow(0 8px 16px rgba(0, 0, 0, 0.58)); }
.fighter-a { left: 48%; top: 62%; opacity: 0.9; animation: xw-fly 17s ease-in-out infinite; }
.fighter-b { right: 25%; top: 31%; width: min(8vw, 104px); opacity: 0.6; animation: xw-fly-b 21s ease-in-out infinite; }
.tie { filter: drop-shadow(0 6px 12px rgba(0, 0, 0, 0.6)); }
.tie-a { left: 39%; top: 16%; width: min(6vw, 80px); opacity: 0.55; animation: tie-bob 13s ease-in-out infinite; }
.tie-b { right: 10%; top: 67%; width: min(4.4vw, 58px); opacity: 0.44; animation: tie-bob 16s ease-in-out infinite reverse; }
.laser-bolt {
  position: absolute;
  height: 2px;
  border-radius: 3px;
  background: linear-gradient(90deg, transparent, #ff6b5f 22%, #fff 55%, #ff6b5f 78%, transparent);
  box-shadow: 0 0 10px rgba(255, 102, 91, 0.85);
  opacity: 0;
  animation: bolt-flash 7.5s ease-in-out infinite;
}
.laser-a { top: 27%; left: 18%; width: 190px; transform: rotate(14deg); }
.laser-b {
  top: 48%; right: 14%; width: 145px; transform: rotate(-23deg);
  background: linear-gradient(90deg, transparent, #8cf18a 22%, #f5fff2 55%, #8cf18a 78%, transparent);
  box-shadow: 0 0 10px rgba(134, 241, 128, 0.8);
  animation-delay: 3.9s;
}
@keyframes sd-drift {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(-12px, 7px, 0); }
}
@keyframes cruiser-drift {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(4deg); }
  50% { transform: translate3d(10px, -7px, 0) rotate(6deg); }
}
@keyframes xw-fly {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(-7deg); }
  50% { transform: translate3d(-20px, 11px, 0) rotate(-3deg); }
}
@keyframes xw-fly-b {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(154deg); }
  50% { transform: translate3d(-14px, -9px, 0) rotate(158deg); }
}
@keyframes tie-bob {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(-5deg); }
  50% { transform: translate3d(8px, -6px, 0) rotate(2deg); }
}
@keyframes bolt-flash {
  0%, 68%, 100% { opacity: 0; }
  72% { opacity: 0.95; }
  76% { opacity: 0.15; }
  80% { opacity: 0.8; }
  84% { opacity: 0; }
}

/* ---------- command shell ---------- */
.menu-shell {
  position: relative;
  z-index: 5;
  width: min(1240px, 95vw);
  height: 100%;
  margin: 0 auto;
  padding: clamp(10px, 1.7vh, 20px) 0 clamp(8px, 1.4vh, 16px);
  display: flex;
  flex-direction: column;
  gap: clamp(9px, 1.5vh, 16px);
  animation: rise 0.55s cubic-bezier(0.16, 0.8, 0.3, 1) both;
}
.menu-topbar {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 8px 12px 8px 10px;
