}
.topbar-sound:hover { color: var(--m-cyan); border-color: var(--m-line-strong); }
.sound-ico { color: var(--m-cyan); font-size: 9px; line-height: 1; }
body.muted .sound-ico { color: #7a8b98; }

/* ---------- chunky buttons ---------- */
.deploy-btn {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 12px 28px 10px;
  overflow: hidden;
  border: 2px solid #ffe9ae;
  border-radius: 12px;
  color: #241708;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.42), transparent 44%),
    linear-gradient(180deg, #ffdd8a 0%, #f3bd58 46%, #dc9a32 100%);
  box-shadow: 0 5px 0 #8d5817, 0 14px 30px rgba(0, 0, 0, 0.38), inset 0 2px 0 rgba(255, 255, 255, 0.6);
  transition: transform 0.12s, filter 0.15s, box-shadow 0.12s;
}
.deploy-btn::after {
  content: "";
