}
.deploy-btn:hover { filter: brightness(1.06); transform: translateY(-1px); }
.deploy-btn:active { transform: translateY(3px); box-shadow: 0 2px 0 #8d5817, 0 7px 18px rgba(0, 0, 0, 0.35); }
