}
.ops-body { position: relative; z-index: 2; padding: 12px 15px 14px; }
.ops-kicker { font-size: 5.8px; font-weight: 900; letter-spacing: 0.16em; color: var(--m-gold); }
.ops-title { display: block; margin-top: 2px; font-family: var(--font-head); font-size: clamp(20px, 2vw, 28px); letter-spacing: 0.06em; color: #f8eddb; line-height: 1; }
.ops-body p { margin: 6px 0 10px; font-size: 8px; line-height: 1.45; color: #9db0bf; }
.ops-stats { display: flex; gap: 1px; border: 1px solid rgba(129, 191, 222, 0.13); border-radius: 8px; overflow: hidden; }
.ops-stats > div { flex: 1; padding: 6px 7px; background: rgba(8, 15, 24, 0.5); border-right: 1px solid rgba(129, 191, 222, 0.1); }
.ops-stats > div:last-child { border-right: 0; }
.ops-stats b { display: block; font-family: var(--font-head); font-size: 16px; color: #f6daa0; line-height: 1; }
.ops-stats span { display: block; margin-top: 2px; font-size: 5px; font-weight: 900; letter-spacing: 0.13em; color: #8398a8; }
.ops-link {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%;
  margin-top: 9px;
  padding: 6px 2px 0;
  border-top: 1px solid rgba(129, 191, 222, 0.12);
  color: #bfe9fb;
  font-size: 6.5px;
  font-weight: 900;
  letter-spacing: 0.14em;
}
.ops-link i { font-style: normal; font-size: 12px; color: var(--m-gold); transition: transform 0.15s; }
.ops-link:hover i { transform: translateX(4px); }
.menu-footer {
  flex: none;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 0 5px;
  font-size: 6.3px; font-weight: 800; letter-spacing: 0.15em; color: #728594; text-transform: uppercase;
}
.footer-note { color: #596a78; }

/* ---------- shared page headers ---------- */
.page-head {
  flex: none;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 14px;
  padding: 0 4px;
}
.page-head .menu-back { justify-self: start; align-self: start; margin-top: 3px; }
.page-title { text-align: center; }
.page-title .start-eyebrow { justify-content: center; margin-bottom: 2px; font-size: 6.4px; gap: 7px; }
.page-title .start-eyebrow span { width: 20px; }
.page-title h1 {
  margin: 0;
  font-family: var(--font-head);
  font-size: clamp(24px, 2.9vw, 38px);
  font-weight: 900;
  line-height: 0.98;
  letter-spacing: 0.07em;
  color: #f6ecdc;
  text-shadow: 0 4px 0 rgba(5, 9, 14, 0.4), 0 8px 24px rgba(0, 0, 0, 0.5);
}
.page-title p { margin: 4px 0 0; font-size: 8px; line-height: 1.4; color: #99adbc; }
.menu-back {
  padding: 5px 8px;
  border: 1px solid rgba(129, 191, 222, 0.2);
  border-radius: 7px;
  background: rgba(10, 18, 28, 0.62);
  color: #a8bdcb;
  font-size: 6.5px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(129, 191, 222, 0.2);
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.menu-back:hover { color: var(--m-gold); border-color: rgba(247, 207, 118, 0.48); background: rgba(24, 34, 48, 0.8); }
.menu-side-note {
  justify-self: end;
  text-align: right;
  color: #8ba0ae;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: 0.14em;
  line-height: 1.4;
  text-transform: uppercase;
}
.menu-side-note b { color: var(--m-gold); font-family: var(--font-head); font-size: 14px; vertical-align: -1px; }

/* ---------- home / command center ---------- */
.home-main {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.9fr);
  gap: clamp(10px, 1.2vw, 16px);
}
.home-feature {
  position: relative;
  display: block;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  padding: 0;
  border: 1px solid var(--m-line);
  border-radius: 18px;
  background: #08111c;
  text-align: left;
  box-shadow: var(--m-shadow), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  isolation: isolate;
  transition: transform 0.16s, border-color 0.16s, box-shadow 0.16s;
}
.home-feature:hover, .home-feature:focus-visible {
  transform: translateY(-3px);
  border-color: rgba(247, 207, 118, 0.52);
  box-shadow: 0 24px 54px rgba(0, 0, 0, 0.48), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.feature-art { position: absolute; inset: 0; z-index: 0; }
.feature-stars {
  position: absolute; inset: 0;
  background-image: radial-gradient(1.5px 1.5px at 18% 22%, #fff4cf, transparent 100%), radial-gradient(1px 1px at 62% 16%, #d6f2ff, transparent 100%), radial-gradient(1.4px 1.4px at 82% 54%, #fff4cf, transparent 100%), radial-gradient(1px 1px at 44% 74%, #d6f2ff, transparent 100%);
  background-size: 230px 190px;
  opacity: 0.5;
}
.feature-planet {
  position: absolute;
  width: min(34vw, 430px);
  aspect-ratio: 1;
  right: -12%; bottom: -46%;
  border-radius: 50%;
  background: radial-gradient(circle at 33% 25%, #d7eef3, #7bb1c4 10%, #3e7188 31%, #1c405a 58%, #0a1727 82%);
  box-shadow: inset -48px -34px 80px rgba(0, 0, 0, 0.8), 0 0 70px rgba(91, 178, 208, 0.18);
}
.feature-planet::before {
  content: "";
  position: absolute; inset: 0;
  border-radius: 50%;
  background: repeating-linear-gradient(170deg, transparent 0 18px, rgba(214, 242, 246, 0.08) 19px 23px, transparent 24px 40px);
}
.feature-horizon {
  position: absolute;
  left: -12%; right: -12%; bottom: -30%;
  height: 58%;
  border-radius: 50% 50% 0 0;
  background: linear-gradient(180deg, rgba(18, 45, 63, 0.1), rgba(7, 16, 26, 0.92) 46%, #050b13 72%);
  box-shadow: 0 -20px 60px rgba(41, 111, 145, 0.16);
}
.feature-ship {
  position: absolute;
  width: min(26vw, 330px);
  right: 4%; top: 18%;
  opacity: 0.72;
  filter: drop-shadow(0 16px 22px rgba(0, 0, 0, 0.62)) drop-shadow(0 0 16px rgba(91, 201, 255, 0.15));
  animation: sd-drift 24s ease-in-out infinite;
}
.feature-copy {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: clamp(16px, 2vw, 26px);
  background: linear-gradient(90deg, rgba(3, 8, 15, 0.94) 0%, rgba(3, 8, 15, 0.74) 42%, rgba(3, 8, 15, 0.08) 76%, transparent 100%);
}
.section-tag {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  padding: 3px 8px;
  border: 1px solid #ffe6a2;
  border-radius: 5px;
  background: linear-gradient(180deg, #f8d987, #dda038);
  color: #251809;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: 0.17em;
  box-shadow: 0 2px 0 rgba(109, 66, 15, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.55);
}
.section-tag.alt { background: linear-gradient(180deg, #77c8e6, #2d82b1); border-color: #a9e7ff; color: #071a25; box-shadow: 0 2px 0 rgba(9, 53, 78, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.45); }
.feature-title {
  margin-top: 9px;
  font-family: var(--font-head);
  font-size: clamp(32px, 4.4vw, 58px);
  font-weight: 900;
  line-height: 0.86;
  letter-spacing: 0.055em;
  color: #faf0df;
  text-shadow: 0 4px 0 rgba(5, 9, 14, 0.55), 0 12px 28px rgba(0, 0, 0, 0.55);
}
.feature-desc {
  display: block;
  margin-top: 12px;
  max-width: 360px;
  font-size: clamp(8px, 0.82vw, 10px);
  line-height: 1.5;
  color: #b6c6d2;
}
.feature-map {
  display: inline-flex;
  align-self: flex-start;
  margin-top: 12px;
  padding: 4px 8px;
  border: 1px solid rgba(247, 207, 118, 0.26);
  border-radius: 5px;
  background: rgba(247, 207, 118, 0.07);
  color: #e7c885;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: 0.12em;
}
.feature-cta {
  display: flex; align-items: center; gap: 7px;
  margin-top: auto;
  padding-top: 12px;
  color: #ffe19a;
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: 0.15em;
}
.feature-cta i { font-style: normal; font-size: 15px; transition: transform 0.15s; }
.home-feature:hover .feature-cta i { transform: translateX(4px); }

.home-side { display: grid; grid-template-rows: 1.12fr 0.88fr; gap: clamp(10px, 1.2vw, 16px); min-height: 0; }
.side-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-height: 0;
  overflow: hidden;
  padding: clamp(12px, 1.4vw, 18px);
  border: 1px solid var(--m-line);
  border-radius: 16px;
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.05), transparent 46%, rgba(247, 207, 118, 0.03)),
    linear-gradient(165deg, rgba(23, 37, 54, 0.92), rgba(7, 13, 22, 0.94));
  text-align: left;
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transition: transform 0.16s, border-color 0.16s, box-shadow 0.16s;
}
.side-hangar { cursor: pointer; }
.side-hangar:hover, .side-hangar:focus-visible { transform: translateY(-2px); border-color: rgba(139, 224, 255, 0.48); box-shadow: 0 20px 44px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.08); }
.side-card-glow {
  position: absolute; inset: 0;
  background: radial-gradient(90% 100% at 100% 0%, rgba(80, 190, 232, 0.16), transparent 58%);
  pointer-events: none;
}
.side-head { display: flex; align-items: center; justify-content: space-between; width: 100%; gap: 8px; }
.side-arrow { color: var(--m-cyan); font-size: 15px; transition: transform 0.15s; }
.side-hangar:hover .side-arrow { transform: translateX(4px); }
.side-title {
  display: block;
  margin-top: 8px;
  font-family: var(--font-head);
  font-size: clamp(16px, 1.7vw, 23px);
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0.055em;
  color: #f4ead8;
}
.side-desc { display: block; margin-top: 6px; max-width: 92%; font-size: 7.5px; line-height: 1.42; color: #99adbc; }
.hub-tower-preview { display: flex; gap: 3px; margin-top: auto; padding-top: 8px; opacity: 0.72; }
.hub-mini-icon {
  display: grid; place-items: center;
  width: 24px; height: 24px;
  border: 1px solid rgba(129, 191, 222, 0.13);
  border-radius: 6px;
  background: rgba(9, 18, 28, 0.65);
  color: #d8c49b;
}
.hub-mini-icon svg { width: 21px; height: 21px; }
.side-record { background: linear-gradient(165deg, rgba(31, 34, 49, 0.94), rgba(8, 12, 21, 0.95)); }
.record-stats { display: flex; gap: 1px; width: 100%; margin-top: auto; border: 1px solid rgba(129, 191, 222, 0.12); border-radius: 8px; overflow: hidden; }
.record-stats > div { flex: 1; padding: 7px 6px; background: rgba(5, 11, 19, 0.45); border-right: 1px solid rgba(129, 191, 222, 0.1); }
.record-stats > div:last-child { border-right: 0; }
.record-stats b { display: block; font-family: var(--font-head); font-size: 20px; line-height: 1; color: #f6d58f; }
.record-stats span { display: block; margin-top: 2px; font-size: 4.8px; font-weight: 900; letter-spacing: 0.11em; color: #7e93a3; }
.record-note { display: block; margin-top: 8px; font-size: 6.7px; line-height: 1.4; color: #8499a8; }

/* ---------- bottom command dock ---------- */
.menu-dock {
  flex: none;
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 5px;
  padding: 5px;
  border: 1px solid var(--m-line);
  border-radius: 15px;
  background:
    linear-gradient(180deg, rgba(29, 44, 61, 0.95), rgba(8, 14, 23, 0.96)),
    radial-gradient(80% 100% at 50% 0%, rgba(128, 210, 245, 0.08), transparent 70%);
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(12px);
}
.dock-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  min-width: 96px;
  padding: 6px 12px 5px;
  border: 1px solid transparent;
  border-radius: 10px;
  color: #a7bccb;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent);
  transition: color 0.15s, background 0.15s, border-color 0.15s, transform 0.12s;
}
.dock-btn svg { width: 19px; height: 19px; margin-bottom: 1px; opacity: 0.9; }
.dock-btn b { font-family: var(--font-head); font-size: 8px; letter-spacing: 0.1em; line-height: 1; }
.dock-btn small { font-size: 5.2px; font-weight: 900; letter-spacing: 0.14em; opacity: 0.58; line-height: 1.1; }
.dock-btn:hover, .dock-btn:focus-visible {
  color: #eaf7ff;
  border-color: rgba(129, 191, 222, 0.3);
  background: linear-gradient(180deg, rgba(88, 148, 180, 0.22), rgba(20, 36, 52, 0.3));
}
.dock-btn:active { transform: translateY(1px); }
.dock-primary {
  color: #2a1a08;
  border-color: #ffe6a0;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.38), transparent 48%),
    linear-gradient(180deg, #ffdc87, #e4a53c);
  box-shadow: 0 3px 0 #8d5817, inset 0 1px 0 rgba(255, 255, 255, 0.6);
}
.dock-primary svg { opacity: 1; }
.dock-primary small { opacity: 0.7; }
.dock-primary:hover, .dock-primary:focus-visible {
  color: #1d1105;
  border-color: #fff3cc;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.45), transparent 48%),
    linear-gradient(180deg, #ffe39a, #ecb451);
}
.dock-btn.sound-toggle { border-bottom: 1px solid transparent; }
.dock-btn.sound-toggle:hover { border-color: rgba(129, 191, 222, 0.3); }

/* ---------- star map ---------- */
.map-main, .hangar-main { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: clamp(8px, 1.3vh, 13px); }
.map-grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(9px, 1.1vw, 15px);
  margin: 0;
}
.map-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  border: 1px solid var(--m-line);
  border-radius: 16px;
  background: linear-gradient(170deg, rgba(21, 35, 51, 0.95), rgba(6, 12, 20, 0.97));
  text-align: left;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transition: transform 0.16s, border-color 0.16s, box-shadow 0.16s;
}
.map-tile-available { cursor: pointer; }
.map-tile-available:hover, .map-tile-available:focus-visible {
  transform: translateY(-4px);
  border-color: rgba(247, 207, 118, 0.6);
  box-shadow: 0 24px 52px rgba(0, 0, 0, 0.48), 0 0 0 1px rgba(247, 207, 118, 0.14) inset;
}
.map-tile-locked { opacity: 0.66; filter: saturate(0.55) brightness(0.8); }
.map-art {
  position: relative;
  display: block;
  flex: none;
  height: 53%;
  min-height: 138px;
  overflow: hidden;
  background: #111827;
}
.map-tile-available .map-art { height: 53%; }
.map-art-tag {
  position: absolute;
  left: 10px; bottom: 9px;
  padding: 3px 7px;
  border: 1px solid rgba(174, 227, 247, 0.32);
  border-radius: 4px;
  background: rgba(4, 10, 17, 0.68);
  color: #c9eaf6;
  font-size: 5.4px;
  font-weight: 900;
  letter-spacing: 0.15em;
  backdrop-filter: blur(4px);
}
.map-ready, .map-lock {
  position: absolute;
  top: 9px; right: 9px;
  padding: 4px 7px;
  border-radius: 4px;
  font-size: 5.7px;
  font-weight: 900;
  letter-spacing: 0.13em;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
}
.map-ready { border: 1px solid rgba(139, 212, 107, 0.55); background: rgba(43, 92, 34, 0.72); color: #d3ffbd; }
.map-lock { border: 1px solid rgba(255, 255, 255, 0.2); background: rgba(4, 9, 15, 0.7); color: #c1cbd2; }
.map-info { display: flex; flex: 1; flex-direction: column; gap: 4px; padding: clamp(9px, 1.1vw, 13px); min-height: 0; }
.map-kicker { color: var(--m-gold); font-size: 5.8px; font-weight: 900; letter-spacing: 0.15em; }
.map-title { font-family: var(--font-head); font-size: clamp(17px, 1.8vw, 23px); font-weight: 900; line-height: 1; letter-spacing: 0.045em; color: #f6ecdb; }
.map-desc { color: #9cafbd; font-size: 7.2px; line-height: 1.42; }
.map-chip-row { display: flex; flex-wrap: wrap; gap: 3px; margin-top: auto; padding-top: 4px; }
.map-chip-row span {
  padding: 2px 5px;
  border: 1px solid rgba(129, 191, 222, 0.16);
  border-radius: 3px;
  background: rgba(8, 16, 26, 0.55);
  color: #8fa8b7;
  font-size: 4.9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}
.map-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding-top: 7px;
  border-top: 1px solid rgba(129, 191, 222, 0.11);
  font-size: 6px;
  font-weight: 900;
  letter-spacing: 0.1em;
}
.map-status b { color: #ffe29b; }
.map-status em { color: #7e93a3; font-style: normal; }
.map-tile-available .map-status b { font-size: 7.5px; }
.map-tile-locked .map-status b { color: #9aa7b1; }
.map-screen .space-bg, .hangar-screen .space-bg { filter: saturate(0.88) brightness(0.76); }

/* ---------- hangar ---------- */
.hangar-lead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: clamp(7px, 1vw, 11px) clamp(10px, 1.3vw, 15px);
  border: 1px solid rgba(129, 191, 222, 0.17);
  border-left: 3px solid rgba(247, 207, 118, 0.7);
  border-radius: 10px;
  background: linear-gradient(90deg, rgba(247, 207, 118, 0.07), rgba(20, 35, 51, 0.5));
}
.hangar-lead b { display: block; margin-bottom: 2px; color: var(--m-gold); font-size: 6.3px; font-weight: 900; letter-spacing: 0.18em; }
.hangar-lead p { margin: 0; max-width: 800px; color: #9db1c0; font-size: 7.5px; line-height: 1.42; }
.hangar-stamp {
  flex: none;
  padding: 4px 8px;
  border: 1px solid rgba(247, 207, 118, 0.42);
  border-radius: 5px;
  color: var(--m-gold);
  font-family: var(--font-head);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  transform: rotate(-4deg);
  white-space: nowrap;
  opacity: 0.92;
}
.hangar-roster {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: minmax(0, 1fr);
  gap: clamp(7px, 0.9vw, 11px);
}
.hangar-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  padding: clamp(9px, 1.1vw, 13px);
  border: 1px solid var(--m-line);
  border-radius: 14px;
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.045), transparent 46%),
    linear-gradient(165deg, rgba(23, 37, 54, 0.94), rgba(7, 13, 22, 0.95));
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transition: transform 0.16s, border-color 0.16s, box-shadow 0.16s;
}
.hangar-card::before {
  content: "";
  position: absolute;
  left: 0; top: 18%; bottom: 18%;
  width: 2px;
  border-radius: 2px;
  background: var(--accent, #7fe2ff);
  box-shadow: 0 0 10px var(--accent, #7fe2ff);
  opacity: 0.85;
}
.hangar-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent, #7fe2ff) 52%, transparent);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.hangar-card-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(80% 80% at 0% 0%, color-mix(in srgb, var(--accent, #7fe2ff) 16%, transparent), transparent 58%);
}
.hangar-card-top { position: relative; display: flex; align-items: center; gap: 9px; }
.hangar-card-icon {
  display: grid; place-items: center;
  width: clamp(44px, 4.4vw, 56px);
  height: clamp(44px, 4.4vw, 56px);
  flex: none;
  border: 1px solid color-mix(in srgb, var(--accent, #7fe2ff) 34%, transparent);
  border-radius: 11px;
  background: radial-gradient(circle at 38% 30%, color-mix(in srgb, var(--accent, #7fe2ff) 18%, transparent), rgba(7, 14, 23, 0.8) 72%);
  color: var(--accent, #7fe2ff);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1);
}
.hangar-card-icon svg { width: 76%; height: 76%; }
.hangar-card-id { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.hangar-role { font-size: 5.5px; font-weight: 900; letter-spacing: 0.17em; color: var(--accent, #7fe2ff); }
.hangar-card-id b { font-family: var(--font-head); font-size: clamp(12px, 1.2vw, 15px); letter-spacing: 0.04em; color: #f4ead9; line-height: 1.05; }
.hangar-card-id small { font-size: 5.5px; font-weight: 800; letter-spacing: 0.09em; color: #7f94a4; }
.hangar-tier {
  margin-left: auto;
  align-self: flex-start;
  padding: 3px 5px;
  border: 1px solid rgba(247, 207, 118, 0.24);
  border-radius: 4px;
  background: rgba(247, 207, 118, 0.06);
  color: #d7bb7d;
  font-size: 4.9px;
  font-weight: 900;
  letter-spacing: 0.1em;
  white-space: nowrap;
}
.hangar-card p {
  position: relative;
  margin: 6px 0 5px;
  font-size: 7.2px;
  line-height: 1.4;
  color: #94a9b8;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.hangar-meters { position: relative; display: flex; flex-direction: column; gap: 3px; margin-top: auto; }
.hangar-meters span { display: grid; grid-template-columns: 26px minmax(0, 1fr); align-items: center; gap: 6px; }
.hangar-meters em { font-style: normal; font-size: 4.9px; font-weight: 900; letter-spacing: 0.12em; color: #7f94a4; }
.hangar-meters i { display: block; height: 4px; overflow: hidden; border-radius: 2px; background: rgba(255, 255, 255, 0.08); }
.hangar-meters i b { display: block; height: 100%; border-radius: 2px; background: linear-gradient(90deg, var(--accent, #7fe2ff), color-mix(in srgb, var(--accent, #7fe2ff) 30%, white)); box-shadow: 0 0 6px color-mix(in srgb, var(--accent, #7fe2ff) 55%, transparent); }
.hangar-pips { position: relative; display: flex; align-items: center; gap: 3px; margin-top: 6px; }
.hangar-pips i { width: 12px; height: 3px; border-radius: 2px; background: rgba(255, 255, 255, 0.12); }
.hangar-pips i.on { background: var(--accent, #7fe2ff); box-shadow: 0 0 6px var(--accent, #7fe2ff); }
.hangar-pips span { margin-left: auto; font-size: 4.8px; font-weight: 900; letter-spacing: 0.11em; color: #6e8393; }
.hangar-foot { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.hangar-foot > span { color: #7d919f; font-size: 5.7px; font-weight: 900; letter-spacing: 0.12em; }
.hangar-foot .deploy-btn { padding: 8px 20px 7px; }
.hangar-foot .deploy-btn span { font-size: 13px; }
.hangar-foot .deploy-btn small { font-size: 5.3px; }

/* ---------- modal / end screen polish ---------- */
.modal-card {
  border: 1px solid rgba(129, 191, 222, 0.3);
  background: linear-gradient(165deg, rgba(23, 37, 54, 0.97), rgba(7, 12, 20, 0.98));
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.modal-card .eyebrow { color: var(--m-gold); }
.end-screen { background: radial-gradient(ellipse at 50% 42%, #0b1a2a, #04070c 72%); }
.end-wrap .deploy-btn { border-radius: 11px; }

/* ---------- menu responsive ---------- */
@media (max-width: 1080px) {
  .menu-shell { width: 96vw; }
  .start-main { grid-template-columns: minmax(0, 1.12fr) minmax(270px, 0.88fr); gap: 20px; }
  .home-main { grid-template-columns: minmax(0, 1.42fr) minmax(270px, 0.92fr); }
  .resource-chip small { display: none; }
  .hangar-card p { -webkit-line-clamp: 1; }
}
@media (max-width: 860px) {
  .commander-meta { display: none; }
  .resource-chip { padding: 4px 6px; }
  .resource-chip small { display: none; }
  .start-main { grid-template-columns: minmax(0, 1.25fr) minmax(230px, 0.75fr); gap: 14px; }
  .game-logo { font-size: clamp(42px, 7.6vw, 62px); }
  .home-main { grid-template-columns: minmax(0, 1.35fr) minmax(232px, 0.85fr); }
  .feature-desc { max-width: 290px; }
  .map-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .map-desc { -webkit-line-clamp: 2; display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden; }
  .hangar-roster { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .hangar-card p { display: none; }
}
@media (max-width: 680px) {
  .menu-topbar { padding: 6px 8px; }
  .menu-brand-copy span { display: none; }
  .menu-brand-copy b { font-size: 11px; }
  .brand-emblem { width: 29px; height: 29px; padding: 5px; }
  .commander-chip { display: none; }
  .resource-row { gap: 4px; }
  .topbar-sound { padding: 5px 7px; }
  .start-main { grid-template-columns: 1fr; }
  .start-ops { display: none; }
  .start-hero { max-width: 540px; }
  .home-main { grid-template-columns: 1fr; }
  .home-side { display: none; }
  .map-shell .page-title p, .hangar-shell .page-title p { display: none; }
  .map-grid { grid-template-columns: 1fr; overflow-y: auto; padding-bottom: 2px; }
  .map-tile { min-height: 210px; }
  .hangar-roster { grid-template-columns: 1fr; overflow-y: auto; }
  .hangar-lead { display: none; }
  .hangar-foot > span { display: none; }
  .menu-dock { justify-content: stretch; }
  .dock-btn { flex: 1; min-width: 0; }
}
@media (max-height: 640px) {
  .menu-shell { gap: 7px; padding-top: 8px; padding-bottom: 7px; }
  .menu-topbar { padding-top: 5px; padding-bottom: 5px; }
  .brand-emblem { width: 28px; height: 28px; }
  .menu-brand-copy b { font-size: 11.5px; }
  .start-main { gap: 16px; }
  .start-tag { margin-top: 9px; font-size: 10px; }
  .start-cta-row { margin-top: 12px; }
  .big-deploy { padding: 11px 25px 9px; min-width: 178px; }
  .big-deploy span { font-size: 19px; }
  .btn-metal { padding: 8px 13px 7px 11px; }
  .btn-metal-icon { width: 25px; height: 25px; }
  .how-row { margin-top: 10px; }
  .how-item { padding: 6px 8px; }
  .start-ops .ops-art { height: 88px; }
  .ops-body { padding: 9px 12px 10px; }
  .ops-body p { display: none; }
  .ops-stats > div { padding: 5px 6px; }
  .feature-title { font-size: clamp(29px, 4vw, 44px); }
  .feature-desc { margin-top: 8px; font-size: 8px; }
  .feature-map { margin-top: 7px; }
  .side-title { font-size: 16px; }
  .side-desc { font-size: 7px; }
  .menu-dock { padding: 4px; }
  .dock-btn { padding: 4px 10px 4px; }
  .dock-btn svg { width: 17px; height: 17px; }
  .dock-btn b { font-size: 7px; }
  .map-art { min-height: 110px; height: 47%; }
  .map-tile-available .map-art { height: 47%; }
  .map-desc { display: none; }
  .hangar-lead { padding: 6px 9px; }
  .hangar-lead p { display: none; }
  .hangar-card { padding: 8px 9px; }
  .hangar-card p { display: none; }
  .hangar-card-icon { width: 40px; height: 40px; }
  .hangar-pips { margin-top: 4px; }
  .hangar-foot .deploy-btn { padding: 6px 14px 5px; }
  .hangar-foot .deploy-btn span { font-size: 11px; }
}
@media (max-height: 470px) {
  .menu-shell { gap: 5px; padding-top: 5px; padding-bottom: 4px; }
  .menu-topbar { border-radius: 9px; }
  .menu-brand-copy span, .resource-row, .topbar-sound .sound-ico { display: none; }
  .menu-brand-copy b { font-size: 10px; }
  .start-tag { display: none; }
  .start-cta-row { margin-top: 8px; }
  .how-row { display: none; }
  .game-logo { font-size: clamp(36px, 7vw, 50px); }
  .start-ops { display: none; }
  .start-main { grid-template-columns: 1fr; }
  .menu-footer { font-size: 5.5px; }
  .home-main { grid-template-columns: minmax(0, 1.5fr) minmax(200px, 0.85fr); }
  .home-side { grid-template-rows: 1fr 1fr; }
  .side-desc, .record-note { display: none; }
  .hub-tower-preview { padding-top: 3px; }
  .hub-mini-icon { width: 17px; height: 17px; }
  .hub-mini-icon svg { width: 15px; height: 15px; }
  .dock-btn { flex-direction: row; gap: 5px; padding: 5px 8px; }
  .dock-btn svg { width: 14px; height: 14px; margin: 0; }
  .dock-btn small { display: none; }
  .page-title p, .menu-side-note { display: none; }
  .page-head { grid-template-columns: auto 1fr auto; }
  .page-title { text-align: left; }
  .page-title .start-eyebrow { justify-content: flex-start; }
  .map-art { min-height: 78px; height: 42%; }
  .map-tile-available .map-art { height: 42%; }
  .map-info { gap: 2px; padding: 6px 8px; }
  .map-chip-row { display: none; }
  .hangar-lead { display: none; }
  .hangar-roster { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .hangar-card-icon { width: 32px; height: 32px; }
  .hangar-card-id b { font-size: 11px; }
  .hangar-role, .hangar-card-id small { display: none; }
  .hangar-tier { display: none; }
  .hangar-meters { display: none; }
  .hangar-pips span { display: none; }
  .hangar-foot > span { display: none; }
}

input.oldString:
/* coarse pointers get a bit more spacing */
@media (pointer: coarse) {
  .tower-card:hover { transform: none; }
  .btn-primary, .btn-ghost, .close-btn, .icon-btn, .place-hint button { min-width: 34px; min-height: 34px; }
}

files.patch:
Index: styles.css
===================================================================
--- styles.css
+++ styles.css
@@ -1912,4 +1912,1176 @@
 @media (pointer: coarse) {
   .tower-card:hover { transform: none; }
   .btn-primary, .btn-ghost, .close-btn, .icon-btn, .place-hint button { min-width: 34px; min-height: 34px; }
 }
+
+/* ============================================================
+   MENU V2 — BTD6-inspired Rebel command interface
+   ============================================================ */
+:root {
+  --m-panel: rgba(12, 20, 32, 0.9);
+  --m-panel-2: rgba(25, 39, 56, 0.9);
+  --m-line: rgba(129, 191, 222, 0.2);
+  --m-line-strong: rgba(157, 224, 255, 0.55);
+  --m-cyan: #7fe2ff;
+  --m-cyan-deep: #2b8fd0;
+  --m-gold: #f7cf76;
+  --m-gold-2: #e0a13c;
+  --m-shadow: 0 22px 54px rgba(0, 0, 0, 0.44);
+}
+
+.icon-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
+
+/* ---------- deep-space backdrop ---------- */
+.space-bg {
+  background:
+    radial-gradient(ellipse 56% 44% at 80% 30%, rgba(38, 129, 179, 0.34), transparent 66%),
+    radial-gradient(ellipse 48% 48% at 12% 78%, rgba(112, 62, 160, 0.24), transparent 70%),
+    radial-gradient(ellipse 32% 22% at 52% 12%, rgba(233, 163, 74, 0.1), transparent 70%),
+    radial-gradient(ellipse 120% 110% at 50% 45%, transparent 34%, rgba(0, 0, 0, 0.66) 100%),
+    linear-gradient(155deg, #04070d 0%, #07101d 46%, #0a1726 100%);
+}
+.space-bg::before {
+  content: "";
+  position: absolute;
+  inset: -10%;
+  background:
+    radial-gradient(ellipse 42% 24% at 74% 36%, rgba(67, 178, 219, 0.13), transparent 70%),
+    radial-gradient(ellipse 30% 19% at 20% 68%, rgba(168, 96, 206, 0.1), transparent 72%),
+    repeating-linear-gradient(104deg, transparent 0 120px, rgba(113, 187, 218, 0.022) 122px 124px, transparent 126px 250px);
+  pointer-events: none;
+}
+.space-bg::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background-image:
+    radial-gradient(1.5px 1.5px at 8% 22%, rgba(255, 244, 216, 0.9), transparent 100%),
+    radial-gradient(1px 1px at 19% 66%, rgba(255, 244, 216, 0.62), transparent 100%),
+    radial-gradient(2px 2px at 43% 17%, rgba(213, 241, 255, 0.8), transparent 100%),
+    radial-gradient(1px 1px at 67% 72%, rgba(255, 244, 216, 0.55), transparent 100%),
+    radial-gradient(1.6px 1.6px at 88% 37%, rgba(255, 244, 216, 0.8), transparent 100%);
+  background-size: 460px 390px;
+  opacity: 0.5;
+  pointer-events: none;
+}
+.space-bg-dim { filter: saturate(0.92) brightness(0.86); }
+.nebula {
+  position: absolute;
+  border-radius: 50%;
+  filter: blur(42px);
+  mix-blend-mode: screen;
+  pointer-events: none;
+}
+.nebula-a {
+  width: 64vw; height: 42vh;
+  right: -10vw; top: 1vh;
+  background: radial-gradient(ellipse, rgba(49, 170, 218, 0.34), rgba(41, 72, 160, 0.12) 55%, transparent 72%);
+  animation: nebula-pulse 18s ease-in-out infinite;
+}
+.nebula-b {
+  width: 46vw; height: 38vh;
+  left: -8vw; bottom: -8vh;
+  background: radial-gradient(ellipse, rgba(145, 76, 188, 0.24), rgba(45, 40, 112, 0.08) 56%, transparent 74%);
+  animation: nebula-pulse 23s ease-in-out infinite reverse;
+}
+@keyframes nebula-pulse {
+  0%, 100% { opacity: 0.55; transform: scale(1); }
+  50% { opacity: 0.82; transform: scale(1.05); }
+}
+
+.stars { opacity: 0.62; }
+.stars-b { opacity: 0.28; }
+.planet-main {
+  width: min(52vw, 660px);
+  right: max(-17vw, -170px);
+  top: 7vh;
+  background:
+    radial-gradient(circle at 30% 26%, #d5edf4 0%, #8fc2d1 6%, #51869d 18%, #2b5872 38%, #17314a 59%, #0a1727 79%, #040911 100%);
+  box-shadow:
+    inset -72px -52px 126px rgba(0, 0, 0, 0.86),
+    inset 24px 18px 74px rgba(255, 255, 255, 0.13),
+    0 0 120px rgba(88, 172, 206, 0.18);
+}
+.planet-main::before {
+  background:
+    repeating-linear-gradient(171deg, transparent 0 24px, rgba(205, 238, 244, 0.06) 25px 30px, transparent 31px 50px),
+    radial-gradient(26% 13% at 31% 39%, rgba(238, 251, 253, 0.16), transparent 70%),
+    radial-gradient(34% 10% at 55% 62%, rgba(231, 248, 252, 0.1), transparent 70%),
+    radial-gradient(60% 35% at 38% 28%, rgba(235, 250, 252, 0.14), transparent 70%);
+}
+.planet-main::after {
+  box-shadow:
+    inset -14px 0 42px rgba(159, 220, 240, 0.2),
+    inset 0 0 3px rgba(213, 244, 252, 0.48),
+    0 0 34px rgba(122, 204, 234, 0.08);
+}
+.moon-mini {
+  right: 41%;
+  top: 14%;
+  opacity: 0.58;
+}
+.screen-vignette {
+  position: absolute;
+  inset: 0;
+  z-index: 3;
+  pointer-events: none;
+  background:
+    radial-gradient(ellipse at 50% 46%, transparent 34%, rgba(0, 0, 0, 0.48) 100%),
+    linear-gradient(90deg, rgba(2, 5, 10, 0.64) 0%, transparent 34%, transparent 68%, rgba(2, 5, 10, 0.18) 100%);
+}
+.start-screen .screen-vignette {
+  background:
+    linear-gradient(90deg, rgba(2, 5, 11, 0.9) 0%, rgba(2, 5, 11, 0.62) 35%, rgba(2, 5, 11, 0.12) 72%, transparent 100%),
+    radial-gradient(ellipse at 46% 48%, transparent 30%, rgba(0, 0, 0, 0.36) 100%);
+}
+.start-screen::before, .start-screen::after { content: none; }
+
+/* ---------- proper spacecraft ---------- */
+.ship-layer { position: absolute; inset: 0; pointer-events: none; }
+.ship { position: absolute; display: block; overflow: visible; }
+.ship.destroyer {
+  width: min(37vw, 480px);
+  right: -2vw;
+  top: 12%;
+  opacity: 0.76;
+  filter: drop-shadow(0 18px 26px rgba(0, 0, 0, 0.64)) drop-shadow(0 0 18px rgba(91, 201, 255, 0.18));
+  animation: sd-drift 26s ease-in-out infinite;
+}
+.ship.cruiser {
+  width: min(21vw, 270px);
+  left: -4vw;
+  top: 13%;
+  opacity: 0.34;
+  filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.6));
+  animation: cruiser-drift 34s ease-in-out infinite;
+}
+.ship.fighter { width: min(12vw, 158px); filter: drop-shadow(0 8px 16px rgba(0, 0, 0, 0.58)); }
+.fighter-a { left: 48%; top: 62%; opacity: 0.9; animation: xw-fly 17s ease-in-out infinite; }
+.fighter-b { right: 25%; top: 31%; width: min(8vw, 104px); opacity: 0.6; animation: xw-fly-b 21s ease-in-out infinite; }
+.tie { filter: drop-shadow(0 6px 12px rgba(0, 0, 0, 0.6)); }
+.tie-a { left: 39%; top: 16%; width: min(6vw, 80px); opacity: 0.55; animation: tie-bob 13s ease-in-out infinite; }
+.tie-b { right: 10%; top: 67%; width: min(4.4vw, 58px); opacity: 0.44; animation: tie-bob 16s ease-in-out infinite reverse; }
+.laser-bolt {
+  position: absolute;
+  height: 2px;
+  border-radius: 3px;
+  background: linear-gradient(90deg, transparent, #ff6b5f 22%, #fff 55%, #ff6b5f 78%, transparent);
+  box-shadow: 0 0 10px rgba(255, 102, 91, 0.85);
+  opacity: 0;
+  animation: bolt-flash 7.5s ease-in-out infinite;
+}
+.laser-a { top: 27%; left: 18%; width: 190px; transform: rotate(14deg); }
+.laser-b {
+  top: 48%; right: 14%; width: 145px; transform: rotate(-23deg);
+  background: linear-gradient(90deg, transparent, #8cf18a 22%, #f5fff2 55%, #8cf18a 78%, transparent);
+  box-shadow: 0 0 10px rgba(134, 241, 128, 0.8);
+  animation-delay: 3.9s;
+}
+@keyframes sd-drift {
+  0%, 100% { transform: translate3d(0, 0, 0); }
+  50% { transform: translate3d(-12px, 7px, 0); }
+}
+@keyframes cruiser-drift {
+  0%, 100% { transform: translate3d(0, 0, 0) rotate(4deg); }
+  50% { transform: translate3d(10px, -7px, 0) rotate(6deg); }
+}
+@keyframes xw-fly {
+  0%, 100% { transform: translate3d(0, 0, 0) rotate(-7deg); }
+  50% { transform: translate3d(-20px, 11px, 0) rotate(-3deg); }
+}
+@keyframes xw-fly-b {
+  0%, 100% { transform: translate3d(0, 0, 0) rotate(154deg); }
+  50% { transform: translate3d(-14px, -9px, 0) rotate(158deg); }
+}
+@keyframes tie-bob {
+  0%, 100% { transform: translate3d(0, 0, 0) rotate(-5deg); }
+  50% { transform: translate3d(8px, -6px, 0) rotate(2deg); }
+}
+@keyframes bolt-flash {
+  0%, 68%, 100% { opacity: 0; }
+  72% { opacity: 0.95; }
+  76% { opacity: 0.15; }
+  80% { opacity: 0.8; }
+  84% { opacity: 0; }
+}
+
+/* ---------- command shell ---------- */
+.menu-shell {
+  position: relative;
+  z-index: 5;
+  width: min(1240px, 95vw);
+  height: 100%;
+  margin: 0 auto;
+  padding: clamp(10px, 1.7vh, 20px) 0 clamp(8px, 1.4vh, 16px);
+  display: flex;
+  flex-direction: column;
+  gap: clamp(9px, 1.5vh, 16px);
+  animation: rise 0.55s cubic-bezier(0.16, 0.8, 0.3, 1) both;
+}
+.menu-topbar {
+  position: relative;
+  flex: none;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 18px;
+  padding: 8px 12px 8px 10px;
+  border: 1px solid var(--m-line);
+  border-radius: 14px;
+  background:
+    linear-gradient(180deg, rgba(30, 45, 63, 0.94), rgba(10, 17, 27, 0.92)),
+    radial-gradient(80% 100% at 50% 0%, rgba(128, 210, 245, 0.08), transparent 70%);
+  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.08);
+  backdrop-filter: blur(12px);
+}
+.menu-topbar::after {
+  content: "";
+  position: absolute;
+  left: 18px; right: 18px; bottom: -1px;
+  height: 1px;
+  background: linear-gradient(90deg, transparent, rgba(247, 207, 118, 0.5), transparent);
+  opacity: 0.55;
+}
+.menu-brand { display: flex; align-items: center; gap: 9px; min-width: 0; }
+.brand-emblem {
+  display: grid;
+  place-items: center;
+  width: 34px; height: 34px;
+  flex: none;
+  padding: 6px;
+  border: 1px solid rgba(247, 207, 118, 0.4);
+  border-radius: 50%;
+  color: var(--m-gold);
+  background: radial-gradient(circle at 40% 30%, rgba(247, 207, 118, 0.2), rgba(247, 207, 118, 0.03) 70%);
+  box-shadow: 0 0 22px rgba(247, 207, 118, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.16);
+}
+.brand-emblem svg { width: 100%; height: 100%; }
+.menu-brand-copy { display: flex; flex-direction: column; gap: 1px; }
+.menu-brand-copy b {
+  font-family: var(--font-head);
+  font-size: 13px;
+  letter-spacing: 0.15em;
+  color: #f4ead8;
+}
+.menu-brand-copy span { font-size: 5.8px; font-weight: 800; letter-spacing: 0.2em; color: #8fa8b9; }
+.menu-topright { display: flex; align-items: center; gap: 10px; }
+.commander-chip { display: flex; align-items: center; gap: 8px; }
+.commander-avatar {
+  display: grid; place-items: center;
+  width: 32px; height: 32px;
+  padding: 5px;
+  border: 1.5px solid rgba(247, 207, 118, 0.62);
+  border-radius: 50%;
+  color: var(--m-gold);
+  background: radial-gradient(circle at 38% 28%, #425a6e, #162432 62%, #08111c);
+  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2), 0 0 16px rgba(247, 207, 118, 0.1);
+}
+.commander-avatar svg { width: 100%; height: 100%; }
+.commander-meta { display: flex; flex-direction: column; gap: 3px; }
+.commander-meta b { font-size: 6.5px; letter-spacing: 0.16em; color: #e9d9b8; }
