import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const action = process.argv[2] || 'start';
const out = process.argv[3] || '/tmp/opencode/small.jpg';
const w = Number(process.argv[4] || 1280);
const h = Number(process.argv[5] || 720);
const browser = await chromium.launch({
  headless: true,
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome',
  args: ['--no-sandbox']
});
const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1, isMobile: false, hasTouch: true });
await page.goto('http://localhost:8000/', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);

if (action === 'home') {
  await page.click('#playBtn'); await page.waitForTimeout(600);
} else if (action === 'map') {
  await page.click('#playBtn'); await page.waitForTimeout(300);
  await page.click('#chooseMapBtn'); await page.waitForTimeout(600);
} else if (action === 'hangar') {
  await page.click('#playBtn'); await page.waitForTimeout(300);
  await page.click('#upgradesBtn'); await page.waitForTimeout(600);
} else if (action === 'game') {
  await page.click('#playBtn'); await page.waitForTimeout(250);
  await page.click('#chooseMapBtn'); await page.waitForTimeout(250);
  await page.click('.map-tile-available'); await page.waitForTimeout(1200);
}

await page.screenshot({ path: out, type: 'jpeg', quality: 84 });
await browser.close();
console.log('saved', out, w, h);

