from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.err=[]
    def handle_starttag(self,t,a):
        if t not in ('meta','link','img','br','hr','input','use','path','circle','rect','ellipse','stop'):
            self.stack.append(t)
    def handle_endtag(self,t):
        if t in ('meta','link','img','br','hr','input','use','path','circle','rect','ellipse','stop'): return
        if not self.stack: self.err.append(('extra',t)); return
        if self.stack[-1]!=t:
            self.err.append(('mismatch',t,self.stack[-3:]))
            if t in self.stack:
                while self.stack and self.stack[-1]!=t: self.stack.pop()
                if self.stack: self.stack.pop()
        else: self.stack.pop()
p=P(); p.feed(open('index.html').read()); print('errors',p.err[:10]); print('open tags',p.stack[-10:])
PY

