import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({headless:true, executablePath:'/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome', args:['--no-sandbox']});
for (const [w,h,tag] of [[1920,1080,'1080'],[800,600,'800'],[1366,768,'1366']]) {
  const page = await browser.newPage({viewport:{width:w,height:h}});
  await page.goto('http://localhost:8000/',{waitUntil:'networkidle'}); await page.waitForTimeout(400);
  const info = await page.evaluate(()=>{
    const de=document.documentElement, shell=document.querySelector('.menu-shell').getBoundingClientRect();
    const hero=document.querySelector('.start-hero').getBoundingClientRect();
    return {docH:de.scrollHeight, viewH:innerHeight, shell:{y:Math.round(shell.y),h:Math.round(shell.height),bottom:Math.round(shell.bottom)}, hero:{y:Math.round(hero.y),bottom:Math.round(hero.bottom)}, overflowX:de.scrollWidth-innerWidth};
  });
  console.log(tag, JSON.stringify(info));
  await page.screenshot({path:`/tmp/opencode/final-${tag}.jpg`, type:'jpeg', quality:65});
  await page.close();
}
await browser.close();

import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({headless:true, executablePath:'/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome', args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1280,height:720}});
const errs=[]; page.on('pageerror',e=>errs.push(e.message));
await page.goto('http://localhost:8000/?play=1',{waitUntil:'networkidle'}); await page.waitForTimeout(1200);
await page.locator('.tower-card').first().click(); await page.waitForTimeout(150);
const spots=[[0.18,0.2],[0.3,0.25],[0.42,0.3],[0.55,0.4],[0.65,0.55],[0.3,0.7]];
let before=await page.evaluate(()=>window.__game.towers.length);
for (const [x,y] of spots) {
  const box = await page.evaluate(([x,y])=>{const c=document.querySelector('canvas');const r=c.getBoundingClientRect();return {x:r.x+r.width*x,y:r.y+r.height*y}},[x,y]);
  await page.mouse.click(box.x,box.y); await page.waitForTimeout(120);
  const n=await page.evaluate(()=>window.__game.towers.length);
  if(n>before){ before=n; break; }
}
console.log('towers', before, 'errors', errs);
await browser.close();
